{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "network_partition",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, round(avg(duration)/1e6,1) AS avg_ms FROM abnormal_traces WHERE span_name = 'rate.Rate/GetRates' GROUP BY ALL", "claim": "rate.Rate/GetRates has no server spans in the incident; search's client calls all end in Error after about 20,000 ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM normal_traces WHERE span_name = 'rate.Rate/GetRates' GROUP BY ALL", "claim": "In the normal period rate served about 855 GetRates server spans at about 0.5 ms each."},
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name AS pod, metric, min(value) AS minv, max(value) AS maxv FROM abnormal_metrics WHERE metric = 'k8s.container.restarts' AND attr_k8s_pod_name LIKE 'rate-%' GROUP BY ALL", "claim": "The rate pod shows zero restarts and stays up, so the failure is not a pod crash."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE message = 'Failed to get rates from rate service' GROUP BY ALL", "claim": "Search logs about 1,442 ERROR lines 'Failed to get rates from rate service' during the incident."}
      ]
    },
    {
      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT service_name, metric, round(avg(value),2) AS avg_v, count(*) AS n FROM abnormal_metrics WHERE metric = 'k8s.deployment.available' AND service_name = 'profile' GROUP BY ALL", "claim": "profile deployment availability is 0 for the whole abnormal window, versus 1 in the normal period."},
        {"kind": "metric", "sql": "SELECT attr_k8s_pod_name AS pod, metric, min(value) AS minv, max(value) AS maxv FROM abnormal_metrics WHERE metric = 'k8s.container.restarts' AND attr_k8s_pod_name = 'profile-74b8d7df67-x7zdj' GROUP BY ALL", "claim": "A profile pod's container restarts climb from 1 to 6 during the incident, after 0 in normal."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE span_name = 'profile.Profile/GetProfiles' GROUP BY ALL", "claim": "profile server spans are absent in the incident; frontend's GetProfiles client calls all fail in about 0.01 ms."}
      ]
    }
  ],
  "propagation": [
    {"from": "rate", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, count(*) AS n, round(avg(duration)/1e6,1) AS avg_ms FROM abnormal_traces WHERE span_name IN ('rate.Rate/GetRates','search.Search/Nearby') GROUP BY ALL", "claim": "search's GetRates client calls and its Nearby server spans all end in Error after about 20 s, so search fails as rate is unreachable."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) AS n, round(avg(duration)/1e6,1) AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name = 'HTTP /hotels' GROUP BY ALL", "claim": "Frontend /hotels returns 500 after about 20 s on every request, since its search call fails; /hotels was not failing in normal."}]},
    {"from": "profile", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name = 'HTTP /recommendations' GROUP BY ALL", "claim": "Frontend /recommendations returns Error in about 0.6 ms on every request, after its profile call fails."}]}
  ]
}
